import LibRawModule from './libraw.js';

let ready;
let LibRawClass;
let raw;
let wasm;

async function initLibRaw() {
	ready = (async () => {
		const module = await LibRawModule();
		wasm = module;
		LibRawClass = module.LibRaw;
		raw = new LibRawClass();
	})();
}

initLibRaw();

function isTypedArray(obj) {
	return ArrayBuffer.isView(obj) && !(obj instanceof DataView);
}

self.onmessage = async (event) => {
	const {id, fn, args} = event.data;
	try {
		await ready;
		const out = (typeof raw[fn] === "function" ? raw : wasm)[fn](...args);
		const transferList = [];
		for (const key in out) {
			const value = out[key];
			if (isTypedArray(value))
				transferList.push(value.buffer);
		}
		self.postMessage({id, out}, transferList);
	} catch (err) {
		self.postMessage({id, error: err.message});
	}
};